package dev.shadw.khemet.mobs;

import net.minecraft.client.renderer.entity.EntityRendererProvider;
import net.minecraft.client.renderer.entity.MobRenderer;
import net.minecraft.resources.ResourceLocation;

/** Renders the Tomb Guardian with its own model and texture. Generated by shadw-mod mob. */
public class TombGuardianRenderer extends MobRenderer<TombGuardian, TombGuardianModel.State, TombGuardianModel> {
	private static final ResourceLocation TEXTURE = ResourceLocation.fromNamespaceAndPath("khemet", "textures/entity/tomb_guardian.png");

	public TombGuardianRenderer(EntityRendererProvider.Context context) {
		super(context, new TombGuardianModel(context.bakeLayer(TombGuardianModel.LAYER)), 0.8F);
	}

	@Override
	public TombGuardianModel.State createRenderState() {
		return new TombGuardianModel.State();
	}

	@Override
	public void extractRenderState(TombGuardian entity, TombGuardianModel.State state, float partialTick) {
		super.extractRenderState(entity, state, partialTick);
		state.attackTime = entity.getAttackAnim(partialTick);
		state.airborne = !entity.onGround() && !entity.isNoAi();        // a mob with its AI off is posed, not flying
	}

	@Override
	public ResourceLocation getTextureLocation(TombGuardianModel.State state) {
		return TEXTURE;
	}
}
